import numpy as np
from scipy import stats
import pandas as pd

# Constants
FEATURES = ['feature1', 'feature2', 'feature3', 'feature4', 'feature5']


def task_func(df, dct):
    try:
        if not isinstance(df, pd.DataFrame) or not isinstance(dct, dict):
            return "Invalid input"

        if any(feature not in df.columns for feature in FEATURES):
            return "Invalid input"

        work_df = df.replace(dct)

        result = {}
        for feature in FEATURES:
            values = pd.to_numeric(work_df[feature], errors="raise").dropna().to_numpy()

            if values.size == 0:
                return "Invalid input"

            mean_val = float(np.mean(values))
            median_val = float(np.median(values))
            variance_val = float(np.var(values))

            try:
                mode_res = stats.mode(values, nan_policy="omit", keepdims=False)
            except TypeError:
                mode_res = stats.mode(values, nan_policy="omit")

            mode_arr = np.asarray(mode_res.mode)
            if mode_arr.size == 0:
                return "Invalid input"

            mode_val = mode_arr.reshape(-1)[0]
            if isinstance(mode_val, np.generic):
                mode_val = mode_val.item()

            result[feature] = {
                "mean": mean_val,
                "median": median_val,
                "mode": mode_val,
                "variance": variance_val,
            }

        return result

    except Exception:
        return "Invalid input"
